/* Modern 2D CSS Grid Layout */
.dashboard-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 1.5rem;
  padding: 2rem;
}

// Async Fetching with ES6 async/await
async function fetchUserData(userId) {
  try {
    const res = await fetch(`/api/users/${userId}`);
    if (!res.ok) throw new Error('Network error');
    const data = await res.json();
    return data;
  } catch (err) {
    console.error('Fetch failed:', err);
  }
}

// Discriminated Union & Generic Response
type ApiResponse<T> =
  | { status: 'success'; data: T }
  | { status: 'error'; message: string };

interface User { id: string; name: string; }

import { useState, useMemo } from 'react';

export function Counter({ initial = 0 }) {
  const [count, setCount] = useState(initial);
  const double = useMemo(() => count * 2, [count]);
  return <button onClick={() => setCount(c => c + 1)}>Count: {count} ({double})</button>;
}

import { create } from 'zustand';

export const useStore = create((set) => ({
  bears: 0,
  increasePopulation: () => set((state) => ({ bears: state.bears + 1 })),
}));

// Next.js Server Component with SSG Data Fetching
export default async function Page() {
  const res = await fetch('https://api.example.com/posts', { next: { revalidate: 60 } });
  const posts = await res.json();
  return <div>{posts.map(p => <h2 key={p.id}>{p.title}</h2>)}</div>;
}

import { render, screen } from '@testing-library/react';
import { Counter } from './Counter';

test('renders counter correctly', () => {
  render(<Counter initial={5} />);
  expect(screen.getByText(/Count: 5/i)).toBeInTheDocument();
});
